<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_system_admin();$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);$u=$s->fetch(PDO::FETCH_ASSOC);if(!$u)exit('User not found.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE users SET name=?,email=?,role=?,is_active=? WHERE id=?')->execute([$_POST['name'],$_POST['email'],$_POST['role'],isset($_POST['is_active'])?1:0,$id]);flash('User updated.');header('Location:index.php');exit;}$page_title='Edit User';require __DIR__.'/../includes/header.php';?><h1 class="page-heading mb-4">Edit User</h1><div class="panel"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="col-md-6"><label class="form-label">Full Name</label><input class="form-control" name="name" value="<?=e($u['name'])?>" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" name="email" value="<?=e($u['email'])?>" required></div><div class="col-md-6"><label class="form-label">Role</label><select class="form-select" name="role"><?php foreach(['Admin','Maintenance Staff','Warehouse Staff'] as $x):?><option <?=$u['role']===$x?'selected':''?>><?=$x?></option><?php endforeach?></select></div><div class="col-md-6 d-flex align-items-end"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_active" <?=$u['is_active']?'checked':''?>><label class="form-check-label">Active user</label></div></div><div><button class="btn btn-primary">Save Changes</button></div></form></div><?php require __DIR__.'/../includes/footer.php'; ?>
